TITLE = "Romelu Lukaku retires from Belgium with 94 goals and his roots in Congo"
TAG = "Flavor Sports"
H1 = "Lukaku signs off for Belgium"
DEK = "Belgium's record scorer has retired from international football after 16 years, 135 games and 94 goals. He says he's at peace with it."
