LEAD = ("img/sp-lukaku-wave.jpg", "Lukaku waves to the crowd in Belgium's red", "@aperaw_sport / Instagram")

BODY = [
("p", "Romelu Lukaku has retired from international football. Belgium's all-time top scorer announced it on Instagram on Monday, 16 November 2026, the day after Belgium beat Italy 4-1 in the Nations League. He was on the bench for that game and didn't come on."),
("p", "He is 33, and he leaves with 94 goals in 135 games. Only four men in the history of the game have scored more for their country."),
("quote", "I'm at peace with my decision to stop here. It was amazing.", "Romelu Lukaku, on Instagram"),
("p", "His post was short and plain. He thanked his teammates and coaches, said he went through every emotion possible in 16 years, and told Belgian fans he was proud to have played at four World Cups and three European Championships. He said he enjoyed every single moment."),
("h2", "2010 to 2026", "Sixteen years ", "in red"),
("p", "Lukaku made his Belgium debut in 2010, aged 16. He grew up alongside the country's so-called golden generation, and he went on to become the most prolific scorer the country has ever had."),
("p", "In 2018 he helped Belgium finish third at the World Cup in Russia, still the country's best World Cup finish. At Euro 2020 he scored four goals, though Belgium went out to Italy in the quarter-finals."),
("facts", [("Debut", "2010, aged 16"), ("Caps", "135"), ("Goals", "94 (Belgian record)"), ("World Cups", "4"), ("Euros", "3")]),
("img", "img/sp-lukaku-fans.jpg", "Lukaku thanks Belgium's fans", "@romelulukaku / Instagram"),
("h2", "The last World Cup", "Off the bench, ", "and still scoring"),
("p", "His last tournament said a lot about him. Lukaku went to the 2026 World Cup in North America as a substitute rather than the first name on the team sheet, and he kept scoring anyway."),
("p", "Against New Zealand in Vancouver, his late goal in a 5-1 win took him past Marc Wilmots as Belgium's all-time leading World Cup scorer. He then scored off the bench in the next two games as well, including the fourth goal in a 4-1 win over the United States, the co-hosts, in the round of 16."),
("p", "Belgium's run ended in the quarter-finals in Los Angeles on 10 July, beaten 2-1 by Spain with a late Mikel Merino goal. Lukaku came on as Belgium chased an equaliser that never came. He finished the tournament with eight World Cup goals across his career."),
("h2", "The roots", "Born in Antwerp, ", "rooted in Congo"),
("p", "Lukaku was born in Antwerp to Congolese parents. His father, Roger Lukaku, was a striker from Kinshasa who played for Zaire, now DR Congo, winning 13 caps in the 1990s. Roger moved to Belgium in 1990 and played for clubs including Seraing, Mechelen and Oostende. Even the name Romelu comes from him: it is built from the first letters of Roger Menama Lukaku."),
("p", "Roger died in September 2025, aged 58. In a 2018 essay for The Players' Tribune, Romelu wrote that when things went well, the papers called him the Belgian striker, and when they didn't, he became \"the Belgian striker of Congolese descent\". His point was simple: he was born in Belgium and grew up there."),
("p", "Both things are true, and his Belgium career carried both. He became the most prolific scorer in the country's history while his family story ran back to Kinshasa."),
("img", "img/sp-lukaku-fener.jpg", "Lukaku at Fenerbahçe", "@romelulukaku / Instagram"),
("h2", "What now", "What comes ", "next"),
("p", "Lukaku isn't done with football. He plays his club football in Turkey with Fenerbahçe, the latest stop in a career that has taken him through Anderlecht, Chelsea, West Brom, Everton, Manchester United, Inter Milan, Roma and Napoli."),
("p", "He leaves the national team six goals short of 100, which will bother some fans more than it seems to bother him. Belgium have their Nations League knockout games next spring, and for the first time in 16 years they will go into them without him."),
]

